JOIN exercise_variants variant ON variant.code = seed.variant_code
JOIN muscles muscle ON muscle.code = seed.muscle_code
ON CONFLICT (exercise_variant_id, muscle_id) DO UPDATE SET
    role = EXCLUDED.role,
    activation_level = EXCLUDED.activation_level,
    notes = COALESCE(EXCLUDED.notes, exercise_muscle_activations.notes),
    confidence = EXCLUDED.confidence,
    source_type = EXCLUDED.source_type,
    source_refs = EXCLUDED.source_refs,
    mapping_version = EXCLUDED.mapping_version,
    updated_at = CURRENT_TIMESTAMP;

-- The pull-up family was completed in V11. Mark those records as part of the
-- same catalogue-wide mapping revision without changing their evidence.
UPDATE exercise_muscle_activations activation
SET mapping_version = 2, updated_at = CURRENT_TIMESTAMP
FROM exercise_variants variant
WHERE activation.exercise_variant_id = variant.id
  AND variant.code IN (
      'pullUpPronatedWideGrip',
      'chinUpSupinatedNarrowGrip',
      'pullUpNeutralMediumGrip'
  );

-- V5 predates the evidence columns. Keep those valid anatomical decisions but
-- make every activation DTO explicit and auditable under the v1 catalogue.
UPDATE exercise_muscle_activations
SET confidence = COALESCE(confidence, 'MEDIUM'),
    source_type = COALESCE(source_type, 'BIOMECHANICAL_INFERENCE'),
    source_refs = COALESCE(source_refs, 'CATALOG_V1'),
    mapping_version = 2,
    updated_at = CURRENT_TIMESTAMP
WHERE confidence IS NULL
   OR source_type IS NULL
   OR source_refs IS NULL
   OR mapping_version IS DISTINCT FROM 2;
